content.text:
{
  "name": "实验室板式振荡器",
  "name_en": "Laboratory Plate Shaker",
  "manufacturer": "",
  "description": "用于对实验样品板进行振荡混匀的实验室设备，可按设定转速运行指定时长或连续运行，并支持锁定/解锁样品板以保证振荡过程中的稳定性。",
  "description_en": "A laboratory device used to shake and mix sample plates. It can run at a specified speed for a set duration or continuously, and supports locking/unlocking the plate to keep it secure during shaking.",
  "actions": [
    {
      "action_name": "auto-shake",
      "description": "以指定转速启动振荡，可设置持续时间或连续运行。",
      "description_en": "Start shaking at the specified speed, optionally for a set duration or continuously."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定样品板。",
      "description_en": "Lock the plate."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁样品板。",
      "description_en": "Unlock the plate."
    },
    {
      "action_name": "auto-serialize",
      "description": "序列化设备配置与状态信息。",
      "description_en": "Serialize the device configuration and state information."
    }
  ],
  "tag_hints": [
    "plate shaking",
    "sample mixing",
    "RPM speed control",
    "timed shaking",
    "plate lock",
    "lab automation"
  ]
}

